from pathlib import Path
import json

additions={
'05-001':'''Особенно важно различать личное распоряжение царя и возможности аппарата, который должен был его выполнить. Разрядная запись о назначении показывает служебное решение, но сама по себе не сообщает о качестве снабжения или отношении местных жителей. Закон фиксирует желаемый порядок, а жалоба — конкретный конфликт, причём обычно со слов заинтересованной стороны. Сопоставление позволяет увидеть, где усиление верховной власти сопровождалось более устойчивым управлением, а где приводило к разрушительным действиям. Поэтому длительное правление Ивана нельзя оценить одним показателем: расширение территории, положение подданных и способность учреждений работать после кризиса требуют самостоятельного рассмотрения.''',
'05-002':'''Вопрос о существовании рады удобнее разделить на несколько проверяемых задач. Кто готовил решения, кто участвовал в обсуждении, кто получал поручение и кто отвечал за исполнение? Совпадение людей в нескольких таких ситуациях свидетельствует об устойчивом влиянии, но ещё не доказывает наличия формально учреждённого коллегиального органа. Позднее воспоминание о согласии советников может быть связано с оценкой последующего разрыва с царём. Поэтому границы «рады» нельзя восстанавливать только по одному названию или одному перечню имён. Надёжнее показывать конкретные связи придворного совета, царской воли и действовавших учреждений, отдельно отмечая степень определённости каждого вывода.''',
'05-003':'''Например, появление выборных местных исполнителей меняло распределение обязанностей, но не уничтожало зависимость общины от распоряжений центра. Нужно выяснить, кто мог быть выбран, какими средствами располагал и перед кем отчитывался. Для суда отдельно проверяются установленные платежи, участие местных людей и возможность пожаловаться на злоупотребление. Один и тот же порядок мог укреплять контроль государства и давать некоторым участникам защиту от произвола, не создавая современного равенства перед законом. Поэтому результат реформы оценивается по нескольким группам: служилым людям, посадскому населению и крестьянам. Их интересы могли совпадать в одном вопросе и расходиться в другом.''',
'05-004':'''При чтении соборного решения необходимо различать присутствие, согласие и возможность изменить предложенный вопрос. Подпись под итоговым документом показывает признание сформулированного результата, но не раскрывает всех переговоров. Важно установить, как приглашали участников, какие группы представляли свои требования и кто составлял окончательный текст. Представители города могли говорить от имени общины, не выражая одинаково интересы каждого её жителя. Сравнение собраний разных десятилетий должно учитывать и повод созыва: обсуждение государственной задачи и выбор нового правителя создавали разные условия участия. Нельзя выводить единую неизменную процедуру из нескольких документов, составленных при различном соотношении сил.''',
'05-005':'''Для объяснения конфискаций важно проследить не только потерю владения прежним хозяином, но и то, кто получал землю, какие службы ожидались от нового держателя и что происходило с доходом. Иначе слово «централизация» незаметно превращается в оправдание любого перераспределения. Насилие могло разрушать отношения, на которых держалось снабжение войска и местное управление. Рассказ о Новгородском походе также требует разделять установленный факт репрессий, состав пострадавших и спорные оценки их числа. Несколько поздних текстов, восходящих к одному рассказу, не образуют нескольких независимых подтверждений. Объяснение политического замысла не отменяет отдельного исследования человеческих и хозяйственных последствий.''',
'05-006':'''Военное подчинение столицы ханства и включение всех его прежних связей в московское управление не происходили одним действием. После победы возникали вопросы о гарнизонах, местных посредниках, сборах и распоряжении землёй. Источники, созданные при дворе победителя, чаще подчёркивали успех государя; документы местной жизни позволяют поставить вопросы о переменах для конкретных групп. Нельзя автоматически считать каждого жителя ханства противником Москвы или сторонником нового порядка. Положение знати, торговцев, земледельцев и духовенства различалось. Поэтому изменение границы следует соединять с историей управления и сопротивления, сохраняя различие между результатом завоевания и его позднейшим государственным описанием.''',
'05-007':'''В таком конфликте важно сравнивать цели участников в начале и после изменения состава противников. Доступ к портам, контроль над крепостями и недопущение усиления соседа могли вести к разным решениям. Успех одного похода не гарантировал возможности удерживать все занятые пункты: гарнизонам требовались люди, деньги и связь с основными силами. Мирные соглашения позволяют установить итоговые обязательства, но не раскрывают сами по себе причины военного истощения. Для этого нужно сопоставить внешнюю обстановку с внутренними кризисами. Объяснение поражения только личными качествами правителя или только превосходством противника оставляет без проверки механизм изменения возможностей каждой стороны.''',
'05-008':'''Поэтому сведения о ясаке требуют нескольких уточнений: с какой общины ожидали платёж, кто его собирал, насколько регулярно и чем обеспечивалось требование. Запись о подчинении могла выражать претензию администрации, а не повседневное присутствие её представителей. Острог создавал опорный пункт, но расстояния, сезонность передвижения и сопротивление местных жителей ограничивали возможности гарнизона. С другой стороны, торговый контакт ещё не доказывал политической независимости: обмен мог сочетаться с принуждением. Сопоставляя такие данные, исследователь различает продвижение отряда, закрепление учреждения и изменение жизни населения. Это позволяет избежать описания Сибири как пустого пространства, которое появилось в истории только после московского похода.''',
'05-009':'''После прекращения признанной царской линии особое значение приобретали способы обоснования нового выбора. Родство, служебное положение и поддержка влиятельных групп давали разные основания для притязаний, но ни одно не обеспечивало всеобщего признания автоматически. Сведения о гибели царевича Дмитрия нужно отделять от последующего использования его имени в политической борьбе. Позднейшая уверенность сторонника одной версии не заменяет выяснения времени и происхождения свидетельства. Даже если рассказ точно передаёт слух, это ещё не делает содержание слуха доказанным событием. Так династическая история соединяется с исследованием доверия: важно не только происхождение правителя, но и возможность убедить общество признать его право.''',
'05-010':'''Объясняя причины Смуты, полезно вернуться от решения 1613 года к последовательности распада доверия. Прекращение династической линии создало проблему признания; голод усилил уязвимость людей; борьба претендентов и внешнее вмешательство расширили конфликт. Однако эти обстоятельства действовали через конкретные решения, а не как автоматическая цепь. Неурожай сам по себе не определял, какого правителя признает город, а смена присяги не обязательно выражала свободный выбор жителей. Поэтому исследователь отдельно устанавливает время каждого кризиса и способы его распространения. Это защищает от объяснения всей Смуты одним событием и показывает, почему восстановление власти потребовало не только нового имени на престоле.''',
'05-011':'''Для проверки полезно сопоставлять обещания претендента, решения его окружения и действия местных сторонников. Обещание пожалования свидетельствует о способе привлечения людей, но не подтверждает, что все обещанные условия были исполнены. Документ с присягой фиксирует публичную связь, а не даёт прямого доступа к личной вере участника. При сравнении Лжедмитрия I и Лжедмитрия II важно учитывать изменившуюся обстановку: одинаковое династическое имя использовалось в разных условиях борьбы за власть. Претендент зависел от вооружённых сил и покровителей, которые имели собственные интересы. Поэтому объяснение самозванства требует исследования политического предложения и поддержки, а не только установления настоящей личности человека.''',
'05-012':'''Соглашение о признании Владислава следует рассматривать как набор условий, а не как безусловную передачу всех прав другой стороне. Исследователь спрашивает, какие гарантии ожидали участники, кто мог обеспечить их соблюдение и что происходило при расхождении обещаний с действиями. При этом королевский двор, отдельные магнаты, наёмные отряды и московские сторонники соглашения не составляли единого носителя воли. Их цели могли различаться и меняться. Поздний рассказ об интервенции способен объединить эти действия в одну линию, особенно если описывает события с позиции победившей стороны. Уточнение участников и договорных условий помогает объяснить переход от переговоров к сопротивлению, не стирая насилия внешнего вмешательства.''',
'05-013':'''Работу ополчения полезно изучать через движение ресурсов. Городское решение о сборе денег ещё не означает их поступления в казну; поступление не гарантирует своевременной выплаты жалованья. Между этими этапами стояли учёт, перевозка и доверие к распорядителям. Военный союз также требовал правил решения конфликтов между группами, иначе разногласия могли сорвать общую задачу. Поэтому сведения о временных советах и переписке с городами важны не меньше описаний боя. Они показывают, как создавалась возможность совместного действия при отсутствии признанного центра. Название «народное» не означает одинакового участия всех сословий и не отменяет необходимости исследовать реальный состав движения.''',
'05-014':'''При сравнении ролей руководителей нужно задавать разные вопросы. Кто добивался согласия на сбор средств, кто имел военный авторитет, кто представлял движение в переговорах и кто обеспечивал исполнение решений? Различие функций не уменьшает значение сотрудничества: наоборот, показывает, почему одного личного мужества было недостаточно. Поздний памятник соединяет участников в устойчивый символ гражданского действия, но его художественная программа относится также к эпохе создания памятника. Чтобы изучать решения времени Смуты, необходимы документы самого движения и сведения о городах. Сопоставление памяти и события позволяет понять общественное значение образов Минина и Пожарского, не подменяя организационную историю героическим рассказом.''',
'05-015':'''Особенно важно отделять момент выбора от распространения признания на местах. Решение собрания приобретало практическую силу через доставку грамот, присягу, назначение исполнителей и восстановление поступлений. Задержка с признанием могла быть связана с расстоянием, военной обстановкой или местным конфликтом, а не обязательно с принципиальным отрицанием новой династии. Для изучения представительства следует выяснить, кто подписывал документ и на каком основании выступал от имени группы. Формула согласия не позволяет восстановить все разногласия, но и её торжественность не доказывает, что соглашения не существовало. Источник одновременно закреплял политический результат и помогал сделать его действующим порядком.''',
'05-016':'''Восстановление после Смуты можно исследовать по тому, какие обязательства государство снова было способно исполнять. Сбор средств, обеспечение служилых людей, деятельность местных органов и дипломатические переговоры могли налаживаться с разной скоростью. Поэтому само признание Михаила царём не означает немедленного восстановления всего аппарата. Роль двора и Филарета требует различать формальное положение участников и их участие в конкретных решениях. Для оценки мирных соглашений важна не только территория, но и возможность передышки для страны. Исследователь сравнивает заявленные цели, доступные ресурсы и достигнутые результаты, не превращая последующую устойчивость династии в доказательство неизбежности каждого раннего решения.''',
'05-017':'''Например, принятие нового свода законов показывает стремление упорядочить отношения, но его содержание могло закреплять неравенство и усиливать зависимость части населения. Война требовала дополнительных ресурсов, а способы их получения влияли на городские и сельские конфликты. Для оценки решений Алексея Михайловича нужно связать эти направления, не сводя их к одному характеру царя. Документ о государственном замысле полезно сравнить с жалобой на исполнение и свидетельством о сопротивлении. При этом жалоба также выражает интересы заявителя, а не всех подданных сразу. Так возникает многослойное объяснение правления, в котором институциональные изменения соседствуют с ценой их проведения.''',
'05-018':'''При работе с Уложением сначала определите, к какой категории людей относится норма и какое действие она регулирует. Порядок суда, положение посадского населения и розыск беглых связаны общим государственным устройством, но не являются одной и той же обязанностью. Отдельно нужно выяснить, кому закон давал право требовать исполнения и кто нёс расходы. Если норма усиливала возможности землевладельца, это ещё не означает одинакового результата в каждом уезде. Длительная жизнь свода также не доказывает неизменности всей практики управления. Позднейшие решения могли уточнять применение старого текста, поэтому исследование конкретного дела требует установить не только статью, но и время её использования.''',
'05-019':'''Крепостную зависимость следует описывать через отдельные ограничения: переход, розыск ушедшего человека, наследование его положения и возможность владельца требовать возвращения. Эти элементы складывались не обязательно одновременно, поэтому одну дату нельзя превращать в объяснение всего процесса. Нормативные памятники позволяют проследить изменение признанных правил; дела о спорах помогают увидеть, как семьи пытались действовать внутри ограничений. При сравнении крестьян и других зависимых групп важно не смешивать разные юридические категории. Общее наличие принуждения не делает все положения одинаковыми. Такая точность позволяет показать расширение несвободы без упрощённого представления, будто ранее существовала полностью свободная деревня, а затем один закон изменил всё сразу.''',
'05-020':'''Для участников спора обряд был связан с правильностью богослужения и спасением, поэтому изменение формулы могло восприниматься как угроза всей религиозной жизни. Историческое объяснение должно восстановить это значение, прежде чем оценивать поведение сторон. Вместе с тем убеждённость автора не даёт основания автоматически принимать его описание намерений противника. Нужно различать спор об авторитетном образце, конфликт церковного руководства с царём и государственное принуждение к исполнению решений. Эти процессы пересекались, но не совпадали полностью. Сопоставление автобиографического свидетельства, соборного решения и распоряжения власти показывает разные уровни конфликта, не сводя раскол к личной ссоре или к непонятному современному читателю упрямству.''',
'05-021':'''Сравнивая выступления, сначала выпишите требования, состав участников, способы организации и ответ власти. Совпадение недовольства налогами ещё не делает городской протест и движение на казачьем пограничье одинаковыми. Для одних участников главным могло быть устранение конкретного должностного лица, для других — изменение повинности или сохранение привычного порядка. Публичный призыв от имени царя мог помогать объединению, не означая согласия со всеми действиями правительства. Поэтому важно сопоставлять лозунг с выбранными целями нападения и порядком управления внутри движения. Источники властей чаще фиксировали нарушение порядка; собственные документы участников и свидетельства местной жизни позволяют поставить вопросы, которые обвинительный рассказ оставляет за пределами внимания.''',
'05-022':'''Для сравнения направлений внешней политики полезно построить последовательность обязательств. Перемирие позволяло временно изменить распределение сил, но не обязательно прекращало соперничество; союз создавал ожидания помощи, но не устранял различия интересов. В вопросе украинских земель особенно важно различать решения московского правительства, казацкого руководства и других участников переговоров. Условия одного соглашения нельзя переносить на весь последующий период без проверки. Дипломатический текст фиксирует достигнутую формулу, тогда как переписка и исполнение показывают её практическое значение. Такой подход объясняет изменчивость границ и союзов через конкретные решения, а не через представление о заранее заданном движении к будущей карте.''',
'05-023':'''Чтобы оценить изменение благосостояния, необходимо сопоставить доход с расходами и повинностями. Рост выручки от продажи хлеба мог сочетаться с увеличением платежей, потерей доступа к земле или большей затратой труда. Сведения о рынке показывают обмен, но не всегда раскрывают, кому доставалась прибыль. Государственная политика также имела разные последствия: защита интересов одной группы купцов могла повышать издержки другой. Поэтому экономическую историю нужно связывать с устройством собственности и распределением обязанностей. Даже при расширении связей между районами сохранялись сезонные риски, зависимость от урожая и неодинаковые возможности хозяйств. Обобщение «рынок рос» требует объяснения того, что именно росло и для кого.''',
'05-024':'''Для исследования культурной перемены важно установить не только автора произведения, но и заказчика, способ распространения и предполагаемую аудиторию. Печатная книга могла увеличить число похожих экземпляров, однако доступ к чтению зависел от цены, обучения и социальной среды. Новый образ в изображении человека мог сосуществовать с привычной религиозной задачей, а не обязательно вытеснять её. Поэтому понятие обмирщения требует пояснения: какие именно темы и способы обращения к зрителю изменились? Сравнение нескольких памятников помогает увидеть сосуществование форм. Единичный придворный заказ нельзя без дополнительной проверки считать выражением вкуса всей страны или одинаковой скорости перемен в городе и деревне.''',
'05-025':'''Полезно разобрать одну судебную ситуацию по участникам: кто обращается с требованием, кто рассматривает дело, какие документы нужны и кто получает установленные платежи. Тогда правовой текст перестаёт быть перечнем запретов и раскрывает устройство процедуры. Участие местных представителей могло ограничивать отдельные злоупотребления, но само по себе не устанавливало равенства всех жителей. Нормы о переходе крестьян следует читать в связи с предусмотренными условиями, не подменяя их современным понятием свободного трудового договора. Сопоставление с более ранним Судебником позволяет искать конкретные изменения, однако вывод о практике требует отдельного материала. Точность чтения статьи важнее общей формулы «закон усилил порядок».''',
'05-026':'''Решения Стоглава полезно читать как программу исправления, обращённую к конкретным исполнителям. Требование обучать духовенство указывает на признанную задачу, но не даёт готового подсчёта грамотных священников. Норма об изображении или богослужении устанавливает авторитетный образец, однако её распространение зависело от местных условий. Поэтому исследователь различает предписание собора и последующие свидетельства исполнения. При сравнении со спорами следующего века важно выяснить, какой текст стороны признавали основанием правильности и почему выбирали именно его. Позднейшая критика соборных решений не означает, что первоначальные участники считали себя противниками традиции: они также могли понимать свою деятельность как её защиту.''',
'05-027':'''Свидетельство участника осады особенно ценно близостью к пережитому, но его положение влияет на отбор событий. Автор мог подробнее описывать действия собственной общины и представлять удачный исход как подтверждение её религиозной стойкости. Для реконструкции обороны необходимо отдельно рассмотреть продовольствие, болезни, распределение обязанностей и связь с внешними силами. Не каждый успех вылазки менял общий ход Смуты, а окончание осады не означало немедленного восстановления страны. Поэтому рассказ о монастыре нужно помещать в последовательность событий за его стенами. Так сохраняется значение конкретной обороны, но не возникает впечатления, будто один эпизод самостоятельно решил весь политический кризис.''',
'05-028':'''Для проверки доступности хлеба важно различать наличие запасов и возможность семьи ими воспользоваться. Помощь могла быть объявлена, но расстояния, перевозка, местное распределение и злоупотребления влияли на её получение. Указ о чрезвычайной мере показывает, что власть считала проблемой; он не сообщает автоматически, скольким людям удалось помочь. Сообщения о росте цен также требуют уточнения места и времени: рынок столицы не описывает положение каждой деревни. Наконец, политическое обвинение правителя после бедствия — отдельное свидетельство утраты доверия, а не доказательство его намеренного создания. Такое разделение позволяет связать природные, хозяйственные и политические причины, не смешивая механизм катастрофы с её позднейшим толкованием.'''
}
folder=Path('src/content/lessons')
out=Path('tasks/001-russian-history-course')
snapshot=out/'deep05-before.json'
if snapshot.exists():
 all_applied=all(json.loads((folder/(key+'.json')).read_text())['deep']['text'].endswith(addition) for key,addition in additions.items())
 if all_applied:
  print('All 28 additions are already present; original snapshot preserved.')
  raise SystemExit(0)
 raise SystemExit('An original snapshot already exists; inspect partial changes before running again.')
before={};counts={}
for key,addition in additions.items():
 p=folder/(key+'.json');lesson=json.loads(p.read_text());before[key]={'deep':lesson['deep'].copy(),'status':lesson['status']}
 old=lesson['deep']['text'];lesson['deep']['text']=old+'\n\n'+addition
 assert lesson['deep']['text'].startswith(old+'\n\n')
 count=len(lesson['deep']['text'].split());assert count>=100,(key,count)
 assert lesson['status']==before[key]['status']
 original=json.loads(p.read_text());original['deep']['text']=lesson['deep']['text'];assert original==lesson
 p.write_text(json.dumps(lesson,ensure_ascii=False,indent=2)+'\n');counts[key]=count
snapshot.write_text(json.dumps(before,ensure_ascii=False,indent=2)+'\n')
(out/'deep05-word-counts.json').write_text(json.dumps(counts,ensure_ascii=False,indent=2)+'\n')
print('Expanded',len(counts),'lessons; words:',min(counts.values()),'to',max(counts.values()),'; all original deep prefixes and statuses preserved.')
